package com.convoy.offline;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.InputFilter;
import android.view.*;
import android.widget.*;
import com.google.zxing.*;
import com.google.zxing.common.BitMatrix;
import com.google.zxing.integration.android.IntentIntegrator;
import java.util.*;

/** Consumer onboarding; invitations remain bearer credentials and never enter diagnostics. */
public final class ConvoyOnboarding {
 public interface Host { void startHost(String name,String car); void join(ConvoyInvite invite,String name,String car); void advanced(); void crew(); void changed(); }
 private final Activity activity;private final Host host;private final Handler main=new Handler(Looper.getMainLooper());
 private final java.util.concurrent.ExecutorService qrWorker=java.util.concurrent.Executors.newSingleThreadExecutor();
 private AlertDialog inviteDialog,nearbyDialog;private LanDiscovery nearby;private boolean closed;
 private static final int TEXT=0xFFF1F5FA,MUTED=0xFFA6B5C7,BLUE=0xFF438AFF,CARD=0xFF182433;
 private static final String[] CAR_KEYS={"nc","gt86","r34","supra","nsx","gc8","evo6","ae86","z350","na","generic"};
 private static final String[] CAR_NAMES={"Mazda MX-5 NC PRHT","Toyota GT86","Skyline R34","Supra Mk4","Honda NSX","Impreza GC8","Lancer Evo VI","AE86 Trueno","350Z","MX-5 NA","Generic car"};
 public ConvoyOnboarding(Activity activity,Host host){this.activity=activity;this.host=host;}
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private LinearLayout box(){LinearLayout v=new LinearLayout(activity);v.setOrientation(LinearLayout.VERTICAL);v.setPadding(dp(20),dp(8),dp(20),dp(12));return v;}
 private TextView text(String s,int size){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(TEXT);t.setPadding(0,dp(6),0,dp(6));return t;}
 private Button button(LinearLayout parent,String label,Runnable action){Button b=new Button(activity);b.setText(label);b.setAllCaps(false);b.setTextColor(TEXT);b.setTextSize(15);GradientDrawable d=new GradientDrawable();d.setColor(CARD);d.setCornerRadius(dp(12));b.setBackground(d);b.setMinHeight(dp(48));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.topMargin=dp(8);parent.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 private String name(){return activity.getPreferences(0).getString("name","");}
 private String car(){return activity.getPreferences(0).getString("car","nc");}
 private void profileThen(Runnable action){if(name().trim().isEmpty())editProfile(action);else action.run();}
 public void editProfile(){editProfile(host::changed);}
 private void editProfile(Runnable done){LinearLayout v=box();v.addView(text("Your name",13));EditText name=new EditText(activity);name.setSingleLine(true);name.setTextColor(TEXT);name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(32)});name.setText(name());name.setHint("Driver name");name.setHintTextColor(MUTED);v.addView(name);v.addView(text("Your car",13));Spinner car=new Spinner(activity);car.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,CAR_NAMES));for(int i=0;i<CAR_KEYS.length;i++)if(CAR_KEYS[i].equals(car()))car.setSelection(i);v.addView(car);AlertDialog d=new AlertDialog.Builder(activity).setTitle("Your driver profile").setView(v).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(w->{String n=name.getText().toString().trim();try{ConvoyInvite.safeText(n,32,128,false);}catch(java.io.IOException invalid){name.setError("Use a name of 1–32 characters without control characters");return;}activity.getPreferences(0).edit().putString("name",n).putString("car",CAR_KEYS[car.getSelectedItemPosition()]).apply();ConvoyService s=ConvoyService.current;if(s!=null){s.myName=n;s.myCar=CAR_KEYS[car.getSelectedItemPosition()];}d.dismiss();done.run();}));d.show();}
 public void start(){if(ConvoyService.current!=null){showInvite();return;}profileThen(()->host.startHost(name(),car()));}
 public void joinMenu(){if(ConvoyService.current!=null){host.crew();return;}LinearLayout v=box();AlertDialog d=new AlertDialog.Builder(activity).setTitle("Join Convoy").setView(v).setNegativeButton("Close",null).create();button(v,"Scan QR",()->{d.dismiss();scan();});button(v,"Open Invite",()->{d.dismiss();pasteInvite();});button(v,"Nearby Convoys",()->{d.dismiss();nearby();});button(v,"Advanced",()->{d.dismiss();host.advanced();});d.show();}
 public void scan(){new IntentIntegrator(activity).setDesiredBarcodeFormats(IntentIntegrator.QR_CODE).setPrompt("Scan a Convoy invite").setBeepEnabled(false).setBarcodeImageEnabled(false).addExtra("TRY_HARDER",true).setOrientationLocked(false).initiateScan();}
 public void pasteInvite(){LinearLayout v=box();v.addView(text("Paste a Convoy invite link shared by your host.",14));EditText input=new EditText(activity);input.setTextColor(TEXT);input.setHintTextColor(MUTED);input.setHint("Convoy invite link");input.setMaxLines(4);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(ConvoyInvite.MAX_TOKEN_CHARS+32)});input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);v.addView(input);AlertDialog d=new AlertDialog.Builder(activity).setTitle("Open Invite").setView(v).setNegativeButton("Cancel",null).setPositiveButton("Continue",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(w->{try{ConvoyInvite invite=ConvoyInvite.decode(input.getText().toString().trim(),System.currentTimeMillis());d.dismiss();confirm(invite);}catch(Exception invalid){input.setError("Could not open this invitation. Ask your host for a fresh invite.");}}));d.show();}
 public void acceptLink(String value){try{confirm(ConvoyInvite.decode(value,System.currentTimeMillis()));}catch(Exception invalid){message("Could not open this invitation. It may be invalid or expired.");}}
 private void confirm(ConvoyInvite invite){if(ConvoyService.current!=null){message("End your current convoy before joining another.");return;}new AlertDialog.Builder(activity).setTitle("Join "+invite.convoyName+"?").setMessage("Host: "+invite.hostName+"\n"+invite.driverCount+" driver(s)\n\nConnects locally with encrypted communication. Android may ask you to join the host's Wi-Fi. Keep that connection even if it has no Internet.").setNegativeButton("Cancel",null).setPositiveButton("Join Convoy",(d,w)->profileThen(()->host.join(invite,name(),car()))).show();}
 public void showInvite(){if(inviteDialog!=null&&inviteDialog.isShowing())return;LinearLayout v=box();TextView title=text("Preparing your convoy…",20),count=text("",14);v.addView(title);v.addView(count);ImageView qr=new ImageView(activity);qr.setContentDescription("Preparing convoy QR");qr.setBackgroundColor(Color.WHITE);v.addView(qr,new LinearLayout.LayoutParams(-1,dp(280)));TextView hint=text("Scan to join",14);hint.setGravity(Gravity.CENTER);v.addView(hint);final String[] payload={""};Button share=button(v,"Share Invite",()->{if(payload[0].isEmpty())return;Intent send=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_SUBJECT,"Join my Convoy").putExtra(Intent.EXTRA_TEXT,"Join my Convoy 🚗\n\nTap below to join.\n"+payload[0]);activity.startActivity(Intent.createChooser(send,"Share Convoy invite"));});Button gate=button(v,"Stop accepting new drivers",()->{ConvoyService s=ConvoyService.current;if(s!=null)s.setAccepting(!s.accepting());});button(v,"Open Crew",()->{inviteDialog.dismiss();host.crew();});button(v,"End Convoy",()->{inviteDialog.dismiss();end();});ScrollView inviteScroll=new ScrollView(activity);inviteScroll.addView(v);inviteDialog=new AlertDialog.Builder(activity).setTitle("Convoy ready").setView(inviteScroll).setNegativeButton("Close",null).create();final AlertDialog dialog=inviteDialog;dialog.setOnDismissListener(d->{payload[0]="";qr.setImageDrawable(null);host.changed();});dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);Runnable refresh=new Runnable(){public void run(){if(closed||!dialog.isShowing())return;ConvoyService s=ConvoyService.current;if(s==null||!s.active){title.setText("Preparing your convoy…");share.setEnabled(false);gate.setEnabled(false);qr.setVisibility(View.GONE);}else if(!s.host||!s.secureSession()){title.setText("Your convoy is active");count.setText("Invites are available to the host of a new secure convoy.");qr.setVisibility(View.GONE);share.setEnabled(false);gate.setEnabled(false);}else{title.setText(s.sessionTitle());count.setText(s.driverCount()+" driver(s) • "+s.status);gate.setEnabled(true);gate.setText(s.accepting()?"Stop accepting new drivers":"Accept new drivers");try{String next=s.inviteLink();share.setEnabled(!next.isEmpty());hint.setText(s.accepting()?next.isEmpty()?"Preparing local network…":"Scan to join":"New invitations are paused");qr.setVisibility(next.isEmpty()?View.GONE:View.VISIBLE);if(!next.equals(payload[0])){payload[0]=next;qr.setImageDrawable(null);qr.setContentDescription("Preparing convoy QR");if(!next.isEmpty()){share.setEnabled(true);String rendering=next;qrWorker.execute(()->{try{Bitmap image=qr(rendering,600);main.post(()->{if(!closed&&dialog.isShowing()&&rendering.equals(payload[0])){qr.setImageBitmap(image);qr.setContentDescription("Scan to join this convoy");}else image.recycle();});}catch(WriterException invalid){main.post(()->{if(!closed&&dialog.isShowing())hint.setText("QR unavailable. Share the invite link instead.");});}});}}}catch(Exception failure){share.setEnabled(false);qr.setVisibility(View.GONE);hint.setText("Invitation unavailable. Reopen after your network is ready.");}}main.postDelayed(this,1000);}};main.post(refresh);}
 public void end(){new AlertDialog.Builder(activity).setTitle("End Convoy?").setMessage("Location sharing and voice stop on this phone. Invitations from this session stop working.").setNegativeButton("Keep going",null).setPositiveButton("End Convoy",(d,w)->{activity.stopService(new Intent(activity,ConvoyService.class));host.changed();}).show();}
 private void nearby(){LinearLayout v=box();TextView status=text("Looking on your local Wi-Fi…",14);v.addView(status);LinearLayout rows=box();v.addView(rows);nearbyDialog=new AlertDialog.Builder(activity).setTitle("Nearby Convoys").setView(v).setNegativeButton("Close",null).create();nearby=new LanDiscovery(activity,new LanDiscovery.Listener(){@Override public void onChanged(List<LanDiscovery.Endpoint> found){activity.runOnUiThread(()->{if(nearbyDialog==null||!nearbyDialog.isShowing())return;rows.removeAllViews();if(found.isEmpty())rows.addView(text("No convoys found yet. Join the same Wi-Fi or scan your host's QR to connect.",14));for(LanDiscovery.Endpoint e:found)button(rows,e.metadata.title+"\n"+e.metadata.driverCount+" drivers",()->new AlertDialog.Builder(activity).setTitle(e.metadata.title).setMessage("Ask the host for their QR or invite link. Nearby discovery does not authorise joining.").setPositiveButton("Scan QR",(d,w)->{nearbyDialog.dismiss();scan();}).setNeutralButton("Open Invite",(d,w)->{nearbyDialog.dismiss();pasteInvite();}).setNegativeButton("Close",null).show());});}@Override public void onStatus(String value){activity.runOnUiThread(()->status.setText(value));}});nearbyDialog.setOnDismissListener(d->{if(nearby!=null){nearby.close();nearby=null;}});nearbyDialog.show();try{nearby.discover(null,ConvoyInvite.VERSION,null);}catch(java.io.IOException unavailable){status.setText("Connect to the same Wi-Fi as your host, then try again.");}}
 private static Bitmap qr(String token,int size)throws WriterException{BitMatrix bits=ConvoyQr.encode(token,size);size=bits.getWidth();Bitmap image=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);int[] pixels=new int[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++)pixels[y*size+x]=bits.get(x,y)?Color.BLACK:Color.WHITE;image.setPixels(pixels,0,size,0,0,size,size);return image;}
 private void message(String s){if(!activity.isFinishing())new AlertDialog.Builder(activity).setTitle("Convoy").setMessage(s).setPositiveButton("OK",null).show();}
 public void close(){closed=true;qrWorker.shutdownNow();main.removeCallbacksAndMessages(null);if(inviteDialog!=null)inviteDialog.dismiss();if(nearbyDialog!=null)nearbyDialog.dismiss();if(nearby!=null)nearby.close();}
}
